mapper.select:
SELECT i.inquiry_no,c.application_no,COALESCE(c.policy_no,a.policy_no) policy_no, i.inquiry_status,i.issued_at,i.created_by,i.created_at,i.updated_by,i.updated_at, i.reviewer_id,i.reviewed_at FROM new_contract.underwriting_inquiry i JOIN new_contract.underwriting_case c ON c.underwriting_case_no=i.underwriting_case_no JOIN new_contract.insurance_application a ON a.application_no=c.application_no ORDER BY
c.application_no COALESCE(c.policy_no,a.policy_no) i.inquiry_no
DESCASC,i.inquiry_no ASC LIMIT #{pageSize} OFFSET #{offset}
